190	}
191	
192	// TestSellDirectSubmitParityWithModifyOnOverflow 校验直接提交与把有效卖单
193	// 修改到相同参数在整笔金额溢出规则上保持一致：两者都只按可卖持仓接受；
194	// 可卖数量不足仍按原有规则拒绝。
195	func TestSellDirectSubmitParityWithModifyOnOverflow(t *testing.T) {
196		// 路径一：直接提交总量 2、限价 hugeLimit 的卖单被接受。
197		e1, _, sid1 := setupSoldAgainstHugeLimit(t)
198		if o, _ := e1.Order(sid1); o.Status != StatusPending || o.Limit != hugeLimit || o.Qty != 2 {
199			t.Fatalf("直接提交的卖单状态错误: %+v", o)
200		}
201		// 可卖数量不足时，整笔金额能否表示都不能接受：仍按原有规则普通拒绝。
202		before := len(e1.Records())
203		id, err := e1.Sell("A", 3, hugeLimit)
204		if err == nil || errors.Is(err, ErrInt64Overflow) {
205			t.Fatalf("数量超过可卖持仓必须按原有普通规则拒绝，实际 id=%d err=%v", id, err)
206		}
207		if id != 0 {
208			t.Fatalf("被拒委托必须返回零订单编号，实际 %d", id)
209		}
210		expectErr(t, err, "可卖数量不足")
211		if len(e1.Records()) != before+1 || e1.Records()[before].Kind != RecordRejected {
212			t.Fatal("可卖不足只能追加一条拒绝记录")
213		}
214		if e1.Sellable("A") != 0 {
215			t.Fatalf("拒绝不得改变可卖占用: %d", e1.Sellable("A"))
216		}
217	
218		// 路径二：先接受小限价卖单，再修改到与直接提交完全相同的参数，同样成功。
219		e2, _ := NewEngine(100)
220		mustSetMax(t, e2, "A", 100)
221		mustQuote(t, e2, "A", Quote{Seq: 1, Moment: 1, Price: 1}, 1)
222		bid := mustBuy(t, e2, "A", 2, 1)
223		if _, err := e2.Fill(Trade{TradeID: 1, OrderID: bid, Symbol: "A", Side: Buy, Price: 1, Qty: 2}); err != nil {
224			t.Fatal(err)
225		}
226		sid2 := mustSell(t, e2, "A", 2, 1)
227		before = len(e2.Records())
228		if err := e2.Modify(sid2, 2, hugeLimit); err != nil {
229			t.Fatalf("把有效卖单修改到整笔金额溢出的参数必须成功，与直接提交一致: %v", err)
230		}
231		if o, _ := e2.Order(sid2); o.Status != StatusPending || o.Limit != hugeLimit ||
232			o.Qty != 2 || o.Filled != 0 || o.Remaining() != 2 {
233			t.Fatalf("修改后卖单状态错误: %+v", o)
234		}
235		if e2.Cash() != 98 || e2.Position("A") != 2 || e2.Sellable("A") != 0 {
236			t.Fatalf("修改卖单不得预先改变现金与持仓: cash=%d pos=%d sellable=%d",
237				e2.Cash(), e2.Position("A"), e2.Sellable("A"))
238		}
239		if len(e2.Records()) != before+1 || e2.Records()[before].Kind != RecordModified {
240			t.Fatalf("真实修改应只追加一条修改记录，实际新增 %d 条", len(e2.Records())-before)
241		}
242	
243		// 两条路径接受的订单在后续成交结算上行为一致：首笔成交入账、次笔现金溢出拒绝。
244		for i, e := range []*Engine{e1, e2} {
245			// e1 的卖单仍挂 2 股；e2 的卖单刚改好也是 2 股。
246			id := sid1
247			if i == 1 {
248				id = sid2
249			}
250			if _, err := e.Fill(Trade{TradeID: int64(10 + i), OrderID: id, Symbol: "A",
251				Side: Sell, Price: hugeLimit, Qty: 1}); err != nil {
252				t.Fatalf("路径 %d 首笔成交应正常入账: %v", i, err)
253			}
254			if _, err := e.Fill(Trade{TradeID: int64(20 + i), OrderID: id, Symbol: "A",
255				Side: Sell, Price: hugeLimit, Qty: 1}); !errors.Is(err, ErrInt64Overflow) {
256				t.Fatalf("路径 %d 第二笔现金加总溢出必须返回 ErrInt64Overflow，实际 %v", i, err)
257			}
258			if o, _ := e.Order(id); o.Status != StatusPartial || o.Filled != 1 || o.Remaining() != 1 {
259				t.Fatalf("路径 %d 拒绝后前一笔成交与剩余卖单必须保留: %+v", i, o)
260			}
261		}
262	}
