92		}
93		if e.ReservedCash() != 0 || e.AvailableCash() != 906 {
94			t.Fatalf("两笔买单的 31 现金占用必须全部释放: reserved=%d available=%d",
95				e.ReservedCash(), e.AvailableCash())
96		}
97		// 卖单未被风险保护撤销：仍为部分成交，继续占用 4 股，可卖数量为 8-4=4。
98		if e.Sellable("A") != 4 {
99			t.Fatalf("卖单剩余 4 股占用必须保留，可卖数量应为 4: sellable=%d", e.Sellable("A"))
100		}
101	
102		// 风险状态：成交价 3 只用于现金结算，剩余持仓按有效报价 8 估值，
103		// 净值 906+8×8=970、亏损 30 达到上限，已限制增险。
104		st := e.RiskStatus()
105		if !st.Open || st.Day != 1 || st.Baseline != 1000 || st.LossLimit != 30 {
106			t.Fatalf("开日基准与上限应保持: %+v", st)
107		}
108		if !st.Restricted || st.Equity != 970 || st.Loss != 30 {
109			t.Fatalf("成交后应触线且按报价 8 估值: %+v", st)
110		}
111	
112		// 卖单查询：总量 6、已成交 2、剩余 4 保留，仍为部分成交、无撤销原因；
113		// 与两笔买单的已撤销状态并存、互不覆盖。
114		o, ok := e.Order(ask)
115		if !ok {
116			t.Fatal("卖单必须仍可查询")
117		}
118		if o.Qty != 6 || o.Filled != 2 || o.Status != StatusPartial || o.Remaining() != 4 ||
119			o.Limit != 3 || o.Reason != "" {
120			t.Fatalf("卖单应保持部分成交并保留剩余 4 股占用，不得被风险保护撤销: %+v", o)
121		}
122	
123		// 两笔买单均被撤销、剩余量归零，撤销原因按亏损触线解释，不得写成持仓限额不足。
124		for _, id := range []int64{bidA, bidB} {
125			bo, _ := e.Order(id)
126			if bo.Status != StatusCanceled || bo.Remaining() != 0 {
127				t.Fatalf("买单 %d 必须被风险保护撤销: %+v", id, bo)
128			}
129			if !strings.Contains(bo.Reason, "亏损 30") || !strings.Contains(bo.Reason, "上限 30") {
130				t.Fatalf("买单 %d 的撤销原因必须按亏损 30、上限 30 解释: %q", id, bo.Reason)
131			}
132			if strings.Contains(bo.Reason, "持仓限额") {
133				t.Fatalf("买单 %d 的撤销原因不得写成持仓限额不足: %q", id, bo.Reason)
134			}
135		}
136	
137		// 新增记录恰好 4 条，顺序为：成交 → 当日首次触线 → 撤销 bidB（编号大）→ 撤销 bidA。
138		recs := e.Records()
139		newRecs := recs[recsBefore:]
140		if len(newRecs) != 4 {
141			t.Fatalf("应只新增 4 条记录（成交、触线、两笔撤单），实际 %d 条", len(newRecs))
142		}
143	
144		// 1) 成交记录：成交价 3 单独保存；报价快照是当时已生效的估值价 8
145		// （seq2、时刻 2），两者不能混用；剩余 4 取成交记账后、撤单前的口径。
146		fr := newRecs[0]
147		if fr.Kind != RecordFilled || fr.TradeID != 2 || fr.OrderID != ask || fr.Side != Sell {
148			t.Fatalf("第一条应为卖出成交记录: %+v", fr)
149		}
150		if fr.TradePrice != 3 || fr.Qty != 2 || fr.Filled != 2 || fr.Remaining != 4 {
151			t.Fatalf("成交记录应保存成交价 3、本次 2、累计 2、当时剩余 4: %+v", fr)
152		}
153		if !fr.QuoteValid || fr.QuoteSeq != 2 || fr.QuoteMoment != 2 || fr.QuotePrice != 8 {
154			t.Fatalf("成交记录的报价定位必须锚定估值价 8（seq2、时刻 2），不得混入成交价 3: %+v", fr)
155		}
156		if fr.RiskDay != 1 || fr.RiskBaseline != 1000 || fr.RiskEquity != 970 ||
157			fr.RiskLoss != 30 || fr.RiskLimit != 30 || fr.RiskRestrict {
158			t.Fatalf("成交记录应携带记账后、触线前的风险快照（尚未限制）: %+v", fr)
159		}
160	
161		// 2) 触线记录：来源是该笔卖出成交，关联成交编号 2；固化基准 1000、净值 970、
162		// 亏损与上限 30；估值报价定位只含当时持仓的 A（seq2、时刻 2、价格 8），
163		// B 只有未成交买单、无持仓，不进入持仓估值报价。
164		tr := newRecs[1]
165		if tr.Kind != RecordRiskTriggered {
166			t.Fatalf("第二条应为当日首次触线记录: %+v", tr)
167		}
168		if tr.RiskTrigger != RiskTriggerTrade || tr.RiskRefSeq != 2 || tr.RiskRefMoment != 0 {
169			t.Fatalf("触线来源必须是成交 2（成交编号），不得挂到报价或其他来源: trigger=%s ref=%d moment=%d",
170				tr.RiskTrigger, tr.RiskRefSeq, tr.RiskRefMoment)
171		}
172		if tr.RiskDay != 1 || tr.RiskBaseline != 1000 || tr.RiskEquity != 970 ||
173			tr.RiskLoss != 30 || tr.RiskLimit != 30 || !tr.RiskRestrict {
174			t.Fatalf("触线快照必须固化基准 1000、净值 970、亏损与上限 30: %+v", tr)
175		}
176		if len(tr.RiskQuoteRefs) != 1 ||
177			tr.RiskQuoteRefs[0] != (RiskQuoteRef{Symbol: "A", Seq: 2, Moment: 2, Price: 8}) {
178			t.Fatalf("触线估值报价定位必须只含 A 的 seq2@时刻2 价格 8（B 无持仓不参与）: %+v", tr.RiskQuoteRefs)
179		}
180		if !strings.Contains(tr.Reason, "亏损 30") || !strings.Contains(tr.Reason, "上限 30") {
181			t.Fatalf("触线原因必须写明亏损 30 与上限 30: %q", tr.Reason)
182		}
183	
184		// 3) 撤销记录：按订单编号从大到小，先 bidB 后 bidA；均固化亏损 30 与上限 30，
185		// 原因说明风险保护撤单，不得写成持仓限额不足。
186		cb := newRecs[2]
187		if cb.Kind != RecordCanceled || cb.OrderID != bidB || cb.Symbol != "B" || cb.Side != Buy {
188			t.Fatalf("第三条应为先撤编号更大的 B 买单: %+v", cb)
189		}
190		if cb.Qty != 3 || cb.Filled != 0 || cb.Remaining != 3 {
191			t.Fatalf("B 买单撤销记录应注明取消剩余 3 股: %+v", cb)
192		}
193		if !cb.QuoteValid || cb.QuoteSeq != 1 || cb.QuoteMoment != 1 || cb.QuotePrice != 5 {
194			t.Fatalf("B 买单撤销记录报价定位应为 B 的 seq1@时刻1 价格 5: %+v", cb)
195		}
196		ca := newRecs[3]
197		if ca.Kind != RecordCanceled || ca.OrderID != bidA || ca.Symbol != "A" || ca.Side != Buy {
198			t.Fatalf("第四条应为后撤编号较小的 A 买单: %+v", ca)
199		}
200		if ca.Qty != 2 || ca.Filled != 0 || ca.Remaining != 2 {
201			t.Fatalf("A 买单撤销记录应注明取消剩余 2 股: %+v", ca)
202		}
203		if !ca.QuoteValid || ca.QuoteSeq != 2 || ca.QuoteMoment != 2 || ca.QuotePrice != 8 {
204			t.Fatalf("A 买单撤销记录报价定位应为 A 的 seq2@时刻2 价格 8: %+v", ca)
205		}
206		for i, cr := range []Record{cb, ca} {
207			if cr.RiskDay != 1 || cr.RiskBaseline != 1000 || cr.RiskEquity != 970 ||
208				cr.RiskLoss != 30 || cr.RiskLimit != 30 || !cr.RiskRestrict {
209				t.Fatalf("撤单记录 %d 必须固化触线时的亏损 30 与上限 30: %+v", i, cr)
210			}
211			if !strings.Contains(cr.Reason, "亏损 30") || !strings.Contains(cr.Reason, "上限 30") {
212				t.Fatalf("撤单记录 %d 的原因必须以亏损 30、上限 30 解释: %q", i, cr.Reason)
213			}
214			if strings.Contains(cr.Reason, "持仓限额") {
215				t.Fatalf("撤单记录 %d 的原因不得写成持仓限额不足: %q", i, cr.Reason)
216			}
217		}
218		if countRiskRecords(e) != 1 {
219			t.Fatal("一个交易日只能有一条触线记录")
220		}
221	
222		// 限制持续：两合约的新买单都被拒绝。
223		if _, err := e.Buy("A", 1, 1); err == nil {
224			t.Fatal("触线限制后 A 的新买单必须拒绝")
225		}
226		if _, err := e.Buy("B", 1, 5); err == nil {
227			t.Fatal("触线限制后 B 的新买单必须拒绝")
228		}
229	
230		// 卖单剩余 4 股之后仍可按合法成交价（不低于限价 3）结算：按价格 4 成交，
231		// 现金结算用成交价 4（906+16=922），剩余持仓估值仍用报价 8。
232		res2, err := e.Fill(Trade{TradeID: 3, OrderID: ask, Symbol: "A", Side: Sell, Price: 4, Qty: 4})
233		if err != nil {
234			t.Fatalf("卖单保留的剩余 4 股必须仍可成交: %v", err)
235		}
236		if res2.Status != StatusFilled || res2.Filled != 6 || res2.Remaining != 0 {
237			t.Fatalf("剩余 4 股成交后卖单应全部成交: %+v", res2)
238		}
239		if e.Cash() != 922 || e.Position("A") != 4 || e.Sellable("A") != 4 {
240			t.Fatalf("剩余成交应按价格 4 结算现金: cash=%d pos=%d sellable=%d",
241				e.Cash(), e.Position("A"), e.Sellable("A"))
242		}
243		if st := e.RiskStatus(); !st.Restricted || st.Equity != 954 || st.Loss != 46 {
244			t.Fatalf("剩余持仓仍按报价 8 估值且限制不解除: %+v", st)
245		}
246		if o2, _ := e.Order(ask); o2.Status != StatusFilled || o2.Filled != 6 {
247			t.Fatalf("卖单应全部成交: %+v", o2)
248		}
249		if countRiskRecords(e) != 1 {
250			t.Fatal("已限制后卖单剩余成交不得重复产生触线记录")
251		}
252	}
253	
254	// TestRiskPartialSellFillBelowLimitKeepsOrdersAndReserve 覆盖未触线路径：同样的
255	// 部分卖出在亏损上限 31 时只完成结算（亏损 30 < 31），卖单剩余占用正确保留，
256	// 两笔买单与 31 现金占用保持有效，不增加触线或风险撤销记录。
257	func TestRiskPartialSellFillBelowLimitKeepsOrdersAndReserve(t *testing.T) {
258		e, bidA, bidB, ask := riskSellSetup(t, 31)
259	
260		recsBefore := len(e.Records())
261		res, err := e.Fill(Trade{TradeID: 2, OrderID: ask, Symbol: "A", Side: Sell, Price: 3, Qty: 2})
262		if err != nil {
263			t.Fatalf("卖单部分成交必须成功: %v", err)
264		}
265		if res != (FillResult{TradeID: 2, OrderID: ask, Price: 3, Qty: 2,
266			Filled: 2, Remaining: 4, Status: StatusPartial}) {
267			t.Fatalf("成交结果应为累计 2、剩余 4、部分成交: %+v", res)
268		}
269	
270		// 净值 970、亏损 30 低于上限 31，不触线。
271		st := e.RiskStatus()
272		if st.Restricted || st.Equity != 970 || st.Loss != 30 || st.LossLimit != 31 {
273			t.Fatalf("亏损 30 未达上限 31，不应触线: %+v", st)
274		}
275	
276		// 卖单剩余 4 股占用保留；两笔买单与 31 现金占用继续有效。
277		if e.Cash() != 906 || e.ReservedCash() != 31 || e.AvailableCash() != 875 {
278			t.Fatalf("两笔买单的 31 现金占用必须继续保留: cash=%d reserved=%d available=%d",
279				e.Cash(), e.ReservedCash(), e.AvailableCash())
280		}
281		if e.Position("A") != 8 || e.Sellable("A") != 4 {
282			t.Fatalf("卖单剩余 4 股占用必须保留: pos=%d sellable=%d", e.Position("A"), e.Sellable("A"))
283		}
284		if o, _ := e.Order(ask); o.Status != StatusPartial || o.Filled != 2 || o.Remaining() != 4 {
285			t.Fatalf("卖单应保持部分成交、剩余 4: %+v", o)
286		}
287		for _, id := range []int64{bidA, bidB} {
288			if bo, _ := e.Order(id); bo.Status != StatusPending || bo.Remaining() != bo.Qty {
289				t.Fatalf("未触线时买单 %d 必须继续有效: %+v", id, bo)
290			}
291		}
292	
293		// 只新增一条成交记录，不得有触线或撤销记录。
294		newRecs := e.Records()[recsBefore:]
295		if len(newRecs) != 1 || newRecs[0].Kind != RecordFilled {
296			t.Fatalf("未触线时只能新增一条成交记录，实际 %+v", newRecs)
297		}
298		if countRiskRecords(e) != 0 {
299			t.Fatal("未达上限不得产生触线记录")
300		}
301	
302		// 未触线时新买单仍可接受（额度与现金充足）。
303		if _, err := e.Buy("B", 1, 5); err != nil {
304			t.Fatalf("未触线时新买单必须仍可接受: %v", err)
305		}
306	}
